    // 获取当前用户已解锁的最高关卡（示例逻辑，需对接实际进度存储）
    int maxUnlocked = userProgressService.getMaxUnlockedFlagNumber(userDetails.getUsername());
    if (flagNumber > maxUnlocked + 1) {
        return failed(this).feedback("challenge.flag.locked").build();
