public ResponseEntity<Map<String, String>> login(@RequestParam("user") String user, HttpServletResponse response) {
    // 严格白名单校验，禁止子串匹配
    Set<String> allowedUsers = Set.of("Tom", "Jerry", "Sylvester");
    if (!allowedUsers.contains(user)) {
        response.setStatus(HttpStatus.UNAUTHORIZED.value());
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                .body(Map.of("error", "Invalid username"));
    }

    // 使用强随机 salt + bcrypt 哈希存储密码（此处为演示，实际应查 DB）
    // 此处仅修复 JWT 签发逻辑
    Claims claims = Jwts.claims()
            .setIssuedAt(new Date())
            .setExpiration(new Date(System.currentTimeMillis() + 10L * 24 * 60 * 60 * 1000)) // 10 days
            .setSubject(user)
            .put("admin", false);

    String token = Jwts.builder()
            .setClaims(claims)
            .signWith(SignatureAlgorithm.HS512, TextCodec.BASE64.decode("dmktY3Rvcnk=")) // 临时保留，但应替换为环境变量密钥
            .compact();

    Cookie cookie = new Cookie("access_token", token);
    cookie.setHttpOnly(true);
    cookie.setSecure(true); // HTTPS only
    cookie.setPath("/");
    response.addCookie(cookie);

    return ResponseEntity.ok(Map.of("message", "Login successful"));
}

